package com.ruoyi.framework.web.service;

import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.TimeUnit;
import com.ruoyi.common.constant.Constants;
import com.ruoyi.common.core.domain.model.LoginUser;
import com.ruoyi.common.utils.uuid.IdUtils;
import io.jsonwebtoken.Claims;
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.SignatureAlgorithm;
import io.jsonwebtoken.security.Keys;
import org.springframework.stereotype.Service;

@Service
public class TokenService {

    private static final long MILLIS_MINUTE_TEN = 20 * 60 * 1000L;   // 20 分钟
    private static final long EXPIRE_MS = 30 * 60 * 1000L;           // 30 分钟

    private final RedisCache redisCache;

    public TokenService(RedisCache redisCache) {
        this.redisCache = redisCache;
    }

    public String createToken(LoginUser loginUser) {
        String token = IdUtils.fastSimpleUUID();
        loginUser.setToken(token);
        refreshToken(loginUser);

        Map<String, Object> claims = new HashMap<>();
        claims.put(Constants.LOGIN_USER_KEY, token);   // JWT 只放 UUID
        io.jsonwebtoken.security.SecretKey key = Keys.hmacShaKeyFor(secret.getBytes());
        return Jwts.builder()
            .claims(claims)
            .signWith(key, SignatureAlgorithm.HS256)
            .compact();
    }

    public void refreshToken(LoginUser loginUser) {
        loginUser.setExpireTime(System.currentTimeMillis() + EXPIRE_MS);
        String key = Constants.LOGIN_TOKEN_KEY + loginUser.getToken();
        redisCache.setCacheObject(key, loginUser, (int) (EXPIRE_MS / 1000), TimeUnit.SECONDS);
    }

    public void delLoginUser(String token) {
        redisCache.deleteObject(Constants.LOGIN_TOKEN_KEY + token);   // 强制下线的实现
    }
}

package com.ruoyi.framework.web.service;

import com.ruoyi.common.constant.Constants;
import com.ruoyi.common.core.domain.model.LoginUser;
import io.jsonwebtoken.Claims;
import jakarta.servlet.http.HttpServletRequest;

public class TokenVerify {

    private final TokenService tokenService;

    public TokenVerify(TokenService tokenService) {
        this.tokenService = tokenService;
    }

    public LoginUser getLoginUser(HttpServletRequest request) {
        String bearer = request.getHeader("Authorization");
        if (bearer == null || !bearer.startsWith("Bearer ")) {
            return null;
        }
        String jwt = bearer.substring(7);
        Claims claims = tokenService.parseToken(jwt);            // 验签失败直接抛异常
        String uuid = (String) claims.get(Constants.LOGIN_USER_KEY);
        return tokenService.getLoginUserByUuid(uuid);            // Redis 取登录人（可能已被强制下线）
    }

    public void verifyToken(LoginUser loginUser) {
        long remain = loginUser.getExpireTime() - System.currentTimeMillis();
        if (remain <= TokenService.MILLIS_MINUTE_TEN) {
            tokenService.refreshToken(loginUser);                // 活跃用户滑动续期
        }
    }
}
